import{_ as e,o as r,c as t,a5 as n}from"./chunks/framework.BBWGC1a3.js";const p=JSON.parse('{"title":"游戏库管理","description":"","frontmatter":{},"headers":[],"relativePath":"features/library-management.md","filePath":"features/library-management.md","lastUpdated":1789191177000}'),i={name:"features/library-management.md"};function l(o,a,s,d,c,h){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="游戏库管理" tabindex="-1">游戏库管理 <a class="header-anchor" href="#游戏库管理" aria-label="Permalink to “游戏库管理”">​</a></h1><p>游戏库是 Tyranor Next 的主要入口，负责承接目录授权、游戏扫描、识别结果展示和单游戏操作。</p><h2 id="扫描结果" tabindex="-1">扫描结果 <a class="header-anchor" href="#扫描结果" aria-label="Permalink to “扫描结果”">​</a></h2><p>扫描流程会记录游戏类型、目录位置、可用引擎和最近记录。识别结果会被后续启动流程使用，避免每次启动都重新判断所有文件特征。</p><h2 id="封面获取" tabindex="-1">封面获取 <a class="header-anchor" href="#封面获取" aria-label="Permalink to “封面获取”">​</a></h2><p>封面能力位于应用侧功能抽象层，负责封面来源聚合与批量任务。实际封面可用性取决于来源接口、网络环境和游戏元数据质量。</p><h2 id="单游戏设置" tabindex="-1">单游戏设置 <a class="header-anchor" href="#单游戏设置" aria-label="Permalink to “单游戏设置”">​</a></h2><p>单游戏设置可覆盖默认引擎配置，适合处理特殊封包、脚本差异或需要单独调整参数的游戏。</p><h2 id="文件访问" tabindex="-1">文件访问 <a class="header-anchor" href="#文件访问" aria-label="Permalink to “文件访问”">​</a></h2><p>项目通过 Storage Access Framework 管理外部游戏目录，并使用 <code>documentFile</code> 辅助处理授权后的文件访问。部分原生引擎启动时仍需要真实路径映射。</p>',10)])])}const _=e(i,[["render",l]]);export{p as __pageData,_ as default};
